[CmdletBinding()]param([string]$SourcePath,[string]$CrossVolumeParent)
if(-not $SourcePath){$SourcePath=Join-Path $PSScriptRoot '../updater/castlink-updater.ps1'}
$ErrorActionPreference='Stop'
$base=Join-Path $env:TEMP ('castlink-updater-locations-'+[guid]::NewGuid().ToString('N'))
$savedLocal=$env:LOCALAPPDATA;$script:failures=@();$script:passes=0
function Assert($Condition,$Message){if(-not $Condition){throw $Message}}
function Throws([scriptblock]$Body,$Pattern){try{& $Body}catch{if($_.Exception.Message -match $Pattern){return};throw};throw ('Expected refusal: '+$Pattern)}
function Receipt($Root,$Id,$Logical=$Id){return [pscustomobject]@{schemaVersion=1;installationId=$Id;logicalInstallationId=$Logical;distroName=('CastLink-Server-'+$Id.Substring(0,12));rootPath=$Root;repository='resokol/castlink';releaseTag=('server-wsl-v1.0.8-'+('a'*12));rootfsSha256=('d'*64);phase='ready';locationContract='castlink-wsl-location-v1'}}
function Server($Root,$Id,$Logical=$Id){Protect-CLUDirectory $Root;$s=Receipt $Root $Id $Logical;Write-CLUJson (Join-Path $Root 'installation.json') $s;return $s}
function Registry($Rows){$dir=Join-Path $env:LOCALAPPDATA 'CastLinkServerRegistry';Protect-CLUDirectory $dir;Write-CLUJson (Join-Path $dir 'installations.json') @{schemaVersion=1;owner='castlink-wsl-location-v1';userSid=[Security.Principal.WindowsIdentity]::GetCurrent().User.Value;installations=@($Rows)}}
function Row($Root,$Id,$Active=$Root,$Physical=$Id){return @{logicalId=$Id;selectedRoot=$Root;activeRoot=$Active;installationId=$Physical}}
function Test($Name,[scriptblock]$Body){try{&{. $SourcePath -FunctionsOnly;$env:LOCALAPPDATA=Join-Path $base ([guid]::NewGuid().ToString('N'));Protect-CLUDirectory $env:LOCALAPPDATA;function Get-CLUClientFolders{return @()};function Get-CLUReleases{throw 'Network forbidden in location fixtures'};& $Body};$script:passes++;Write-Output ('PASS '+$Name)}catch{$script:failures+=@($Name+': '+$_.Exception.Message);Write-Output ('FAIL '+$Name+': '+$_.Exception.Message)}}
try{
 Test 'external registered receipt is discovered with stable identity' {$p=Join-Path $base 'outside AppData Кириллица';$null=Server $p ('a'*32);Registry @(Row $p ('a'*32));$r=@(Get-CLUInstallations);Assert ($r.Count -eq 1 -and $r[0].folder -ceq $p -and $r[0].logicalId -ceq ('a'*32)) 'validated external server absent'}
 Test 'missing disk remains unavailable and never adopts a same identity copy' {$p=Join-Path $base 'absent';Registry @(Row $p ('a'*32));$r=@(Get-CLUInstallations);Assert ($r.Count -eq 1 -and $r[0].availability -ceq 'unavailable' -and -not (Test-Path $p)) 'missing installation silently lost or created';$copy=Join-Path $env:LOCALAPPDATA 'CastLinkServer/copied';$null=Server $copy ('a'*32);Throws {Get-CLUInstallations} 'ambiguous|conflict|duplicate'}
 Test 'copied receipt path is rejected' {$p=Join-Path $base 'copy';Protect-CLUDirectory $p;Write-CLUJson (Join-Path $p 'installation.json') (Receipt (Join-Path $base 'original') ('b'*32));Registry @(Row $p ('b'*32));$bad=@(Get-CLUInstallations);Assert ($bad.Count -eq 1 -and $bad[0].availability -ceq 'conflict' -and -not $bad[0].receipt) 'copied receipt became usable'}
 Test 'registry duplicate logical identity is refused' {$p=Join-Path $base 'duplicate';Registry @((Row $p ('a'*32)),(Row ($p+'2') ('a'*32)));Throws {Get-CLUInstallations} 'ambiguous|conflict|duplicate'}
 Test 'registry duplicate physical identity cannot masquerade as two logical servers' {$p=Join-Path $base 'duplicate-physical';Registry @((Row $p ('a'*32) $p ('c'*32)),(Row ($p+'2') ('b'*32) ($p+'2') ('c'*32)));Throws {Get-CLUInstallations} 'ambiguous|conflict|duplicate'}
 Test 'completed relocation tombstone resolves only the exact registered destination' {
  $old=Join-Path $env:LOCALAPPDATA 'CastLinkServer/relocated';$new=Join-Path $base 'relocation-destination';$null=Server $old ('a'*32);$null=Server $new ('a'*32);Registry @(Row $new ('a'*32));$id='12345678901234567890123456789012';$operation=Join-Path $env:LOCALAPPDATA ('CastLinkServerRegistry/operations/'+$id);Protect-CLUDirectory $operation;$journal=Join-Path $operation 'journal.json'
  Write-CLUJson $journal @{schemaVersion=1;id=$id;kind='move';phase='completed';selectedRoot=$old;sourceRoot=$old;destinationRoot=$new;logicalId=('a'*32)};Write-CLUJson (Join-Path $old 'relocated-to.json') @{schemaVersion=1;logicalId=('a'*32);destinationRoot=$new;transactionId=$id};Write-CLUJson (Join-Path $old 'maintenance-transaction.json') @{schemaVersion=1;kind='move';id=$id;selectedRoot=$old;journalSelectedRoot=$old;journal=$journal}
  $rows=@(Get-CLUInstallations);Assert ($rows.Count -eq 1 -and $rows[0].folder -ceq $new) 'old moved source causes duplicate discovery';$rows=@(Get-CLUInstallations $old);Assert ($rows.Count -eq 1 -and $rows[0].folder -ceq $new) 'old explicit selection did not resolve verified destination'
  Write-CLUJson $journal @{schemaVersion=1;id=$id;kind='move';phase='move-wsl';selectedRoot=$old;sourceRoot=$old;destinationRoot=$new;logicalId=('a'*32)};$pending=@(Get-CLUInstallations);Assert (@($pending|Where-Object {$_.availability -ceq 'pending'}).Count -eq 1) 'interrupted tombstone publication hid recovery'
 }
 Test 'successive moves resolve a verified chain and reject cycles and missing links' {
  $a=Join-Path $env:LOCALAPPDATA 'CastLinkServer/first';$b=Join-Path $base 'second';$c=Join-Path $base 'third';foreach($p in @($a,$b,$c)){$null=Server $p ('a'*32)};Registry @(Row $c ('a'*32))
  function Mark($From,$To,$Id){$dir=Join-Path $env:LOCALAPPDATA ('CastLinkServerRegistry/operations/'+$Id);Protect-CLUDirectory $dir;$journal=Join-Path $dir 'journal.json';Write-CLUJson $journal @{schemaVersion=1;id=$Id;kind='move';phase='completed';selectedRoot=$From;sourceRoot=$From;destinationRoot=$To;logicalId=('a'*32)};Write-CLUJson (Join-Path $From 'relocated-to.json') @{schemaVersion=1;logicalId=('a'*32);destinationRoot=$To;transactionId=$Id};Write-CLUJson (Join-Path $From 'maintenance-transaction.json') @{schemaVersion=1;kind='move';id=$Id;selectedRoot=$From;journalSelectedRoot=$From;journal=$journal}}
  Mark $a $b ('b'*32);Mark $b $c ('c'*32);$rows=@(Get-CLUInstallations);Assert ($rows.Count -eq 1 -and $rows[0].folder -ceq $c) 'second move made initial source an ambiguous duplicate';Assert ((Get-CLUInstallations $a).folder -ceq $c) 'initial selection did not resolve two moves'
  Mark $b $a ('c'*32);Assert ((Get-CLUInstallations $a).availability -ceq 'conflict') 'cycle accepted';Remove-Item -LiteralPath (Join-Path $b 'relocated-to.json');Assert ((Get-CLUInstallations $a).availability -ceq 'conflict') 'missing chain link accepted'
 }
 Test 'retired relocation and interrupted publication do not hide unrelated clients' {
  $old=Join-Path $env:LOCALAPPDATA 'CastLinkServer/retired';$new=Join-Path $base 'retired-destination';$receipt=Server $old ('a'*32);$null=Server $new ('a'*32);Registry @();$id='d'*32;$operation=Join-Path $env:LOCALAPPDATA ('CastLinkServerRegistry/operations/'+$id);Protect-CLUDirectory $operation;$journal=Join-Path $operation 'journal.json'
  $j=@{schemaVersion=1;id=$id;kind='move';phase='completed';selectedRoot=$old;sourceRoot=$old;destinationRoot=$new;logicalId=('a'*32);source=$receipt;journal=$journal};Write-CLUJson $journal $j;Write-CLUJson (Join-Path $old 'relocated-to.json') @{schemaVersion=1;logicalId=('a'*32);destinationRoot=$new;transactionId=$id};Write-CLUJson (Join-Path $old 'maintenance-transaction.json') @{schemaVersion=1;kind='move';id=$id;selectedRoot=$old;journalSelectedRoot=$old;journal=$journal}
  function Get-CLUClientFolders{return @('fixture-client')};function Read-CLUClientBuild($Folder){return [pscustomobject]@{channel='client';identity=$Folder;folder=$Folder;label='Unrelated Client'}}
  Remove-Item -LiteralPath $new -Recurse -Force;$rows=@(Get-CLUInstallations);Assert (@($rows|Where-Object {$_.channel -ceq 'client'}).Count -eq 1 -and @($rows|Where-Object {$_.availability -ceq 'retired'}).Count -eq 1) 'removed destination hid Client or adopted old source';Throws {Get-CLUProductPlan @($rows|Where-Object {$_.availability -ceq 'retired'})[0] @() $base} 'retired|unavailable|location'
  $j.phase='move-finish';Write-CLUJson $journal $j;$rows=@(Get-CLUInstallations);Assert (@($rows|Where-Object {$_.channel -ceq 'client'}).Count -eq 1 -and @($rows|Where-Object {$_.availability -ceq 'pending' -and $_.folder -ceq $old}).Count -eq 1) 'pending source recovery inaccessible'
  $j.logicalId='0'*32;Write-CLUJson $journal $j;$rows=@(Get-CLUInstallations);Assert (@($rows|Where-Object {$_.channel -ceq 'client'}).Count -eq 1 -and @($rows|Where-Object {$_.availability -ceq 'conflict'}).Count -eq 1) 'conflicting journal hid unrelated Client'
 }
 Test 'update recovery verifies companions before loading any code and supports old inventories' {
  $root=Join-Path $base 'update-recovery';$null=Server $root ('e'*32);$row=Read-CLUWslInstallation $root;$dir=Join-Path $root 'target';Protect-CLUDirectory $dir;$script:recoveryExecuted=$false;$helpers=@()
  $main='param([switch]$FunctionsOnly);$p=Join-Path $PSScriptRoot "server-wsl-location.ps1";if(Test-Path $p){. $p};function Invoke-CastlinkMaintenance{return @{phase="pending"}}'
  foreach($name in @('server-wsl-maintenance.ps1','server-wsl-maintenance-ui.ps1','server-wsl-location.ps1','server-wsl-maintenance.py','server-wsl-runtime.py','install-server-windows.template.ps1')){$file=Join-Path $dir $name;[IO.File]::WriteAllText($file,$(if($name -ceq 'server-wsl-maintenance.ps1'){$main}else{'# safe fixture'}));Set-CLUCreatedFileOwner $file;$helpers+=@(@{file=$name;size=(Get-Item $file).Length;sha256=(Get-CLUHash $file)})}
  $m=@{schemaVersion=1;channel='server-wsl';repository='resokol/castlink';version='1.0.9';sourceCommit=('b'*40);releaseTag='server-wsl-v1.0.9-bbbbbbbbbbbb';lifecycle=@{schemaVersion=1;runtimeContract='castlink-wsl-pg16-v1';locationContract='castlink-wsl-location-v1';helpers=$helpers}};Write-CLUJson (Join-Path $dir 'manifest.json') $m;$journal=Join-Path $root 'journal.json';$j=@{schemaVersion=1;id='update-fixture';kind='update';selectedRoot=$root;journal=$journal;targetDirectory=$dir;manifestSha256=(Get-CLUHash (Join-Path $dir 'manifest.json'));target=$m};Write-CLUJson $journal $j;Write-CLUJson (Join-Path $root 'maintenance-transaction.json') @{schemaVersion=1;id=$j.id;selectedRoot=$root;journal=$journal};$plan=Get-CLURecoveryPlan $row;$tool=Join-Path $base 'recovery-tool';Protect-CLUDirectory $tool
  $generated=Join-Path $dir 'install-server-windows.ps1';[IO.File]::WriteAllBytes($generated,(([Text.UTF8Encoding]::new($true)).GetPreamble()+[Text.Encoding]::UTF8.GetBytes('# safe fixture')));$null=Get-CLURecoveryPlan $row;[IO.File]::AppendAllText($generated,'tampered');Throws {Get-CLURecoveryPlan $row} 'generated|template';Remove-Item $generated
  $companion=Join-Path $dir 'server-wsl-location.ps1';[IO.File]::WriteAllText($companion,'$script:recoveryExecuted=$true');Throws {Apply-CLUProduct $plan $tool -Recovery} 'checksum|size|companion';Assert (-not $script:recoveryExecuted) 'tampered companion executed before verification';Remove-Item $companion;Throws {Get-CLURecoveryPlan $row} 'checksum|missing|size'
  [IO.File]::WriteAllText($companion,'# safe fixture');$rogue=Join-Path $dir 'unexpected.ps1';[IO.File]::WriteAllText($rogue,'$script:recoveryExecuted=$true');Throws {Get-CLURecoveryPlan $row} 'unexpected|companion|inventory';Remove-Item $rogue
  $m.lifecycle.Remove('locationContract');$m.lifecycle.helpers=@($helpers|Where-Object {$_.file -ceq 'server-wsl-maintenance.ps1'});foreach($entry in $helpers|Where-Object {$_.file -cne 'server-wsl-maintenance.ps1'}){Remove-Item -LiteralPath (Join-Path $dir $entry.file)};Write-CLUJson (Join-Path $dir 'manifest.json') $m;$j.manifestSha256=Get-CLUHash (Join-Path $dir 'manifest.json');Write-CLUJson $journal $j;$legacy=Get-CLURecoveryPlan $row;Apply-CLUProduct $legacy $tool -Recovery;Assert (-not $script:recoveryExecuted) 'legacy recovery loaded extra code'
  [IO.File]::WriteAllText($companion,'$script:recoveryExecuted=$true');Throws {Apply-CLUProduct $legacy $tool -Recovery} 'unexpected|companion|inventory';Assert (-not $script:recoveryExecuted) 'unlisted old-release companion executed'
 }
 Test 'legacy AppData receipts remain discoverable' {$p=Join-Path $env:LOCALAPPDATA 'CastLinkServer/legacy';$null=Server $p ('a'*32);$r=@(Get-CLUInstallations);Assert ($r.Count -eq 1 -and $r[0].folder -ceq $p) 'legacy discovery lost'}
