  $p=Join-Path $base 'cancelled-destination';$null=Server $p ('a'*32);Registry @(Row $p ('a'*32));$id='e'*32;$source=Join-Path $base 'cancelled-source';$operation=Join-Path $env:LOCALAPPDATA ('CastLinkServerRegistry/operations/'+$id);Protect-CLUDirectory $operation;$journal=Join-Path $operation 'journal.json';Write-CLUJson $journal @{schemaVersion=1;id=$id;kind='move';phase='cancelled';journal=$journal;selectedRoot=$source;sourceRoot=$source;destinationRoot=$p;logicalId=('a'*32)};Write-CLUJson (Join-Path $p 'maintenance-transaction.json') @{schemaVersion=1;kind='move';id=$id;selectedRoot=$p;journalSelectedRoot=$source;journal=$journal}
