 Test 'WSL packages stay with selected server volume and reject foreign cache collisions' {
  $p=Join-Path $base 'chosen-volume-server';$null=Server $p ('a'*32);Registry @(Row $p ('a'*32));$r=Read-CLUWslInstallation $p;$tool=Join-Path $env:LOCALAPPDATA 'CastLinkUpdater';Protect-CLUDirectory $tool;$release=[pscustomobject]@{tag_name=('server-wsl-v1.0.9-'+('b'*12));id=42}
  $directory=Get-CLUProductDirectory $r $tool $release;Assert ($directory.StartsWith($p+'\') -and -not $directory.StartsWith($tool+'\')) 'server archives placed on updater volume';Assert ((Get-CLUProductDirectory $r $tool $release) -ceq $directory) 'owned cache cannot resume'
