 }
 Test 'package plan downloads and cleanup use the selected server root' {
  $driveRoot=if($CrossVolumeParent){Join-Path $CrossVolumeParent ('castlink-updater-locations-'+[guid]::NewGuid().ToString('N'))}else{Join-Path $base 'package-plan'}
  if($CrossVolumeParent){Assert ([IO.Path]::GetPathRoot($driveRoot) -ine [IO.Path]::GetPathRoot($env:LOCALAPPDATA)) 'Cross-volume fixture must use a different drive'}
  try{
   $s=Server $driveRoot ('e'*32);Registry @(Row $driveRoot ('e'*32));$r=Read-CLUWslInstallation $driveRoot;$tool=Join-Path $env:LOCALAPPDATA 'CastLinkUpdater';Protect-CLUDirectory $tool
   $script:target=[pscustomobject]@{id=142;tag_name='server-wsl-v1.0.9-bbbbbbbbbbbb';draft=$false;prerelease=$false;assets=@();body='fixture'};$script:payload=@{}
   function Asset($Name,[byte[]]$Bytes){$h=[Security.Cryptography.SHA256]::Create();try{$hash=([BitConverter]::ToString($h.ComputeHash($Bytes))).Replace('-','').ToLowerInvariant()}finally{$h.Dispose()};$url='https://github.com/resokol/castlink/releases/download/'+$script:target.tag_name+'/'+$Name;$script:payload[$url]=$Bytes;$script:target.assets+=@([pscustomobject]@{id=(100+$script:target.assets.Count);name=$Name;state='uploaded';size=$Bytes.Length;digest=('sha256:'+$hash);browser_download_url=$url});return @{file=$Name;size=$Bytes.Length;sha256=$hash}}
   $m=@{schemaVersion=1;channel='server-wsl';repository='resokol/castlink';architecture='amd64';version='1.0.9';sourceCommit=('b'*40);releaseTag=$script:target.tag_name;nativePanel=@{files=@()};lifecycle=@{schemaVersion=1;runtimeContract='castlink-wsl-pg16-v1';postgresMajor=16;supportedSources=@($s.releaseTag);helpers=@()}}
   foreach($name in @('rootfs','sources','upstreamSources','inventory')){$m[$name]=Asset ($name+'.tar.gz') ([Text.Encoding]::UTF8.GetBytes('fixture '+$name))}
   foreach($name in @('server-wsl-maintenance.ps1','server-wsl-maintenance-ui.ps1','server-wsl-location.ps1','server-wsl-maintenance.py','server-wsl-runtime.py','install-server-windows.template.ps1')){$m.lifecycle.helpers+=@(Asset $name ([Text.Encoding]::UTF8.GetBytes('# fixture '+$name)))}
   $null=Asset 'manifest.json' ([Text.Encoding]::UTF8.GetBytes(($m|ConvertTo-Json -Depth 20)))
   function Get-CLURelease($Id){return $script:target};function Receive-CLUUrl($Url,$Destination,$Limit){[IO.File]::WriteAllBytes($Destination,$script:payload[$Url])}
   $plan=Get-CLUProductPlan $r @($script:target) $tool;Assert ($plan.directory.StartsWith($driveRoot+'\') -and (Test-Path (Join-Path $plan.directory 'manifest.json'))) 'Server package escaped selected installation root'
   $null=Receive-CLUWslTools $plan -Complete;Set-CLUProductPending $plan $true;Clear-CLUProductPayload $plan;Assert (Test-Path (Join-Path $plan.directory 'rootfs.tar.gz')) 'pending package archive deleted';[IO.File]::WriteAllText((Join-Path $plan.directory 'foreign.txt'),'retain');Set-CLUProductPending $plan $false;Clear-CLUProductPayload $plan;Assert (-not (Test-Path (Join-Path $plan.directory 'rootfs.tar.gz')) -and (Test-Path (Join-Path $plan.directory 'foreign.txt'))) 'cleanup deleted foreign data or retained completed archive'
  }finally{if(Test-Path -LiteralPath $driveRoot){Remove-Item -LiteralPath $driveRoot -Recurse -Force}}
 }
