 Test 'localized Move is WSL-only and refresh retains logical selection after relocation' {
  Add-Type -AssemblyName PresentationFramework
  $script:moved=$false;$script:uiFailure='';$script:uiCount=0;$script:moveRequests=@();$script:recoverRequests=@()
  $oldRoot=Join-Path $base 'ui-source';$newRoot=Join-Path $base 'ui-destination'
  function Get-CLUInstallations($SelectedRoot){return @([pscustomobject]@{channel='client';identity='client';label='Client'},[pscustomobject]@{channel='server-wsl';identity=('b'*32);logicalId=('a'*32);availability='available';folder=$(if($script:moved){$newRoot}else{$oldRoot});label=$(if($script:moved){'WSL destination'}else{'WSL source'})})}
  function Get-CLUPreferences{ return [pscustomobject]@{automatic=$false;language='en'} }
  function Invoke-CLUUiWork($Operation,$Rows,$Root,$Plan){if($Operation -ceq 'RecoveryPlan'){return [pscustomobject]@{kind='move';language=$Plan}};if($Operation -ceq 'Recover'){$script:recoverRequests+=@(@{root=$Rows.folder;language=$Plan.language});return};if($Operation -cne 'Move'){throw 'Unexpected product operation'};$script:moveRequests+=@(@{root=$Rows.folder;language=$Plan});$script:moved=$true}
  $timer=[Windows.Threading.DispatcherTimer]::new();$timer.Interval=[TimeSpan]::FromMilliseconds(200)
  $timer.Add_Tick({foreach($source in @([Windows.PresentationSource]::CurrentSources)){$w=$source.RootVisual;if($w -is [Windows.Window] -and $w.FindName('Products')){try{$w.FindName('Products').SelectedIndex=0;Assert (-not $w.FindName('Move').IsEnabled) 'Client offered WSL move';$w.FindName('Products').SelectedIndex=1;Assert $w.FindName('Move').IsEnabled 'WSL move unavailable';$w.FindName('Move').RaiseEvent([Windows.RoutedEventArgs]::new([Windows.Controls.Button]::ClickEvent));Assert ($w.FindName('Products').SelectedIndex -eq 1 -and $w.FindName('Products').SelectedItem -ceq 'WSL destination') 'Move refresh lost logical selection';$w.FindName('Refresh').RaiseEvent([Windows.RoutedEventArgs]::new([Windows.Controls.Button]::ClickEvent));Assert ($w.FindName('Products').SelectedIndex -eq 1) 'Refresh lost selected server';$w.FindName('Recover').RaiseEvent([Windows.RoutedEventArgs]::new([Windows.Controls.Button]::ClickEvent));$script:uiCount++}catch{$script:uiFailure=$_.Exception.Message};$w.Close()}}})
  $timer.Start();try{foreach($lang in @('ru','en','zh-CN')){$script:moved=$false;Show-CLUWindow $env:LOCALAPPDATA '' $lang}}finally{$timer.Stop()}
  Assert ($script:uiCount -eq 3 -and -not $script:uiFailure) ('Move WPF failed: '+$script:uiFailure)
  Assert ($script:moveRequests.Count -eq 3 -and @($script:moveRequests|Where-Object {$_.root -cne $oldRoot}).Count -eq 0 -and ($script:moveRequests.language -join ',') -ceq 'ru,en,zh-CN') 'Move launched wrong installation or language'
  Assert ($script:recoverRequests.Count -eq 3 -and @($script:recoverRequests|Where-Object {$_.root -cne $newRoot}).Count -eq 0 -and ($script:recoverRequests.language -join ',') -ceq 'ru,en,zh-CN') 'Recover button dispatched wrong installation or language'
 }
 Test 'real move-cleanup publication keeps one pending server and recovers after source archives are removed' {
  $source=Join-Path $env:LOCALAPPDATA 'CastLinkServer/cleanup-source';$destination=Join-Path $base 'cleanup-destination';$s=Server $source ('e'*32);$release=Join-Path $source 'release';Protect-CLUDirectory $release;$helpers=@()
  foreach($name in @('server-wsl-maintenance.ps1','server-wsl-maintenance-ui.ps1','server-wsl-location.ps1','server-wsl-maintenance.py','server-wsl-runtime.py','install-server-windows.template.ps1')){$file=Join-Path $release $name;[IO.File]::WriteAllText($file,'# cleanup recovery helper');Set-CLUCreatedFileOwner $file;$helpers+=@(@{file=$name;size=(Get-Item $file).Length;sha256=(Get-CLUHash $file)})}
  Write-CLUJson (Join-Path $release 'manifest.json') @{schemaVersion=1;repository='resokol/castlink';channel='server-wsl';architecture='amd64';version='1.0.8';sourceCommit=('a'*40);releaseTag=$s.releaseTag;rootfs=@{file='rootfs.tar.gz';sha256=$s.rootfsSha256};lifecycle=@{schemaVersion=1;runtimeContract='castlink-wsl-pg16-v1';locationContract='castlink-wsl-location-v1';helpers=$helpers}}
  $s|Add-Member NoteProperty releaseManifestSha256 (Get-CLUHash (Join-Path $release 'manifest.json'));Write-CLUJson (Join-Path $source 'installation.json') $s;$d=Server $destination ('e'*32);$d|Add-Member NoteProperty releaseManifestSha256 $s.releaseManifestSha256;Write-CLUJson (Join-Path $destination 'installation.json') $d;Copy-Item -LiteralPath $release -Destination (Join-Path $destination 'release') -Recurse
  [IO.File]::WriteAllText((Join-Path $release 'rootfs.tar.gz'),'owned fixture archive');Remove-Item -LiteralPath (Join-Path $release 'rootfs.tar.gz');Registry @(Row $destination ('e'*32));$id='f'*32;$operation=Join-Path $env:LOCALAPPDATA ('CastLinkServerRegistry/operations/'+$id);Protect-CLUDirectory $operation;$journal=Join-Path $operation 'journal.json';$j=@{schemaVersion=1;id=$id;kind='move';phase='move-cleanup';journal=$journal;selectedRoot=$source;sourceRoot=$source;destinationRoot=$destination;logicalId=('e'*32);source=$s};Write-CLUJson $journal $j
  foreach($root in @($source,$destination)){Write-CLUJson (Join-Path $root 'maintenance-transaction.json') @{schemaVersion=1;kind='move';id=$id;selectedRoot=$root;journalSelectedRoot=$source;journal=$journal}};Write-CLUJson (Join-Path $source 'relocated-to.json') @{schemaVersion=1;logicalId=('e'*32);destinationRoot=$destination;transactionId=$id}
  $direct=Get-CLUInstallations $destination;Assert ($direct.availability -ceq 'pending') 'published destination became available before completed';Throws {Get-CLUMovePlan (Read-CLUWslInstallation $destination) en} 'interrupted|Recover';$rows=@(Get-CLUInstallations);Assert ($rows.Count -eq 1 -and $rows[0].availability -ceq 'pending') 'publication produced duplicate or available logical server';$plan=Get-CLURecoveryPlan $rows[0];Assert ($plan.kind -ceq 'move' -and $plan.lifecycleUi.entry -ceq (Join-Path $release 'server-wsl-maintenance-ui.ps1')) 'cleanup phase lost source recovery helper';Assert (-not (Test-Path (Join-Path $release 'rootfs.tar.gz'))) 'recovery recreated source archive'
  $j.phase='completed';Write-CLUJson $journal $j;$rows=@(Get-CLUInstallations);Assert ($rows.Count -eq 1 -and $rows[0].availability -ceq 'available' -and $rows[0].folder -ceq $destination) 'completed publication did not expose destination'
 }
}finally{$env:LOCALAPPDATA=$savedLocal;if(Test-Path $base){Remove-Item -LiteralPath $base -Recurse -Force}}
if($script:failures.Count){throw ($script:failures -join "`n")};Write-Output ('PASS '+$script:passes+' location regressions')
